INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00047000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 47), 'unit47-lesson1', 'English Proverbs: Wisdom and Advice', 'Proverbs are short, well-known sayings that express a general truth or piece of advice. Learning proverbs helps you understand cultural wisdom and express ideas more effectively in English.', $${"details":[{"concept":"A leopard cannot change its spots.","explanation":"People cannot change their fundamental nature.","example":"He promised to be more patient, but he got angry again. A leopard cannot change its spots.","burmese":"လူတစ်ယောက်ရဲ့ မူလသဘာဝကို ပြောင်းလဲလို့မရဘူး။"},{"concept":"A fool and his money are soon parted.","explanation":"A foolish person quickly loses their money.","example":"He bought another useless gadget. A fool and his money are soon parted.","burmese":"အသိဥာဏ်နည်းတဲ့လူက ငွေကိုမြန်မြန်ဆုံးရှုံးတတ်တယ်။"},{"concept":"A barking dog seldom bites.","explanation":"People who make loud threats rarely carry them out.","example":"Don't worry about his threats. A barking dog seldom bites.","burmese":"အော်ဟစ်ခြိမ်းခြောက်တတ်တဲ့လူက ရှားရှားပါးပါး လုပ်တတ်တယ်။"},{"concept":"A mouse may help a lion.","explanation":"Even small or weak beings can help the powerful.","example":"Don't underestimate the new intern. A mouse may help a lion.","burmese":"အားနည်းတဲ့လူက အားကြီးတဲ့လူကို ကူညီနိုင်တယ်။"},{"concept":"A friend to all is a friend to none.","explanation":"Someone who tries to be friends with everyone truly has no real friends.","example":"He talks to everyone but no one trusts him. A friend to all is a friend to none.","burmese":"အားလုံးနဲ့ သူငယ်ချင်းဖြစ်ချင်တဲ့လူက တကယ့်သူငယ်ချင်းမရှိဘူး။"},{"concept":"All that glitters is not gold.","explanation":"Something that looks valuable or attractive may not be so.","example":"That job offer looks amazing, but check the details. All that glitters is not gold.","burmese":"တောက်ပတဲ့အရာအားလုံး ရွှေမဟုတ်ဘူး။"},{"concept":"All covet, all lose.","explanation":"Greed causes people to lose everything.","example":"He tried to invest in every opportunity and lost everything. All covet, all lose.","burmese":"တစ်ခုတည်းကို လိုချင်ရင် ဆုံးရှုံးတတ်တယ်။"},{"concept":"Blood is thicker than water.","explanation":"Family relationships are stronger than other relationships.","example":"After all the arguments, they still helped each other. Blood is thicker than water.","burmese":"သွေးသားဆက်ဆံက ရေထက်ပိုထူတယ်။"},{"concept":"Better late than never.","explanation":"It is better to do something late than not at all.","example":"She finally apologized. Better late than never.","burmese":"နောက်ကျပေမယ့် မလုပ်တာထက်ပိုကောင်းတယ်။"},{"concept":"Bad news travels fast.","explanation":"Negative information spreads quickly.","example":"Everyone already knows about the mistake. Bad news travels fast.","burmese":"ဆိုးဆိုးရွားရွားသတင်းက မြန်မြန်ပျံ့နှံ့တယ်။"},{"concept":"Charity begins at home.","explanation":"One should take care of family first before helping others.","example":"He donates to strangers but ignores his parents. Charity begins at home.","burmese":"ကျေးဇူးပြုခြင်းက အိမ်မှာစတင်တယ်။"},{"concept":"Don't look a gift horse in the mouth.","explanation":"Do not criticize or find fault with something given to you for free.","example":"The old car they gave you works fine. Don't look a gift horse in the mouth.","burmese":"လက်ဆောင်ရတဲ့မြင်းရဲ့ပါးစပ်ကို မကြည့်ပါနဲ့။"},{"concept":"Don't put all your eggs in one basket.","explanation":"Do not risk everything on a single plan or opportunity.","example":"Apply to many schools, not just one. Don't put all your eggs in one basket.","burmese":"ဥအုန်းအားလုံးကို ခြင်းတစ်ခုထဲမှာ မထားပါနဲ့။"},{"concept":"Don't judge a book by its cover.","explanation":"Do not judge something or someone by outward appearance alone.","example":"The small restaurant has the best food. Don't judge a book by its cover.","burmese":"စာအုပ်ရဲ့အဖုံးကြည့်ပြီး မတရားပါနဲ့။"},{"concept":"Easier said than done.","explanation":"Something is much harder to do than to talk about.","example":"Just quit smoking? Easier said than done.","burmese":"ပြောတာ လုပ်တာထက် လွယ်တယ်။"},{"concept":"Empty vessels make the greatest song.","explanation":"People with little knowledge often talk the most.","example":"He talks the most but knows the least. Empty vessels make the greatest song.","burmese":"အလွတ်ဗူးက အကြီးဆုံးအသံထွက်တယ်။"},{"concept":"Every cloud has a silver lining.","explanation":"There is something good in every bad situation.","example":"Losing that job led to a better one. Every cloud has a silver lining.","burmese":"မိုးတိမ်တိုင်းရဲ့ ငွေရောင်အစွန်းရှိတယ်။"},{"concept":"Easy come, easy go.","explanation":"What is gained easily is lost easily.","example":"He won the lottery and spent it all in a week. Easy come, easy go.","burmese":"လွယ်လွယ်ရတာ လွယ်လွယ်ဆုံးရှုံးတယ်။"},{"concept":"Familiarity breeds contempt.","explanation":"Too much closeness leads to a lack of respect.","example":"They argue all the time now. Familiarity breeds contempt.","burmese":"ရင်းနှီးမှုက အထင်အမြင်သေးခြင်းကို ဖန်တီးတယ်။"},{"concept":"Fools are wise as long as silent.","explanation":"A fool seems wise when they do not speak.","example":"He stayed quiet during the meeting. Fools are wise as long as silent.","burmese":"အသံမထွက်သရွယ် ပါးစပ်မရှိသလို ဉာဏ်ကောင်းတယ်။"},{"concept":"Gardens are not made by sitting in the shade.","explanation":"Success requires effort and hard work.","example":"You need to study if you want to pass. Gardens are not made by sitting in the shade.","burmese":"ဥယျာဉ်ကို အရိပ်ထဲမှာ ထိုင်ပြီး ဖန်တီးလို့မရဘူး။"},{"concept":"Grasp all, lose all.","explanation":"If you try to hold on to everything, you will lose everything.","example":"He took on too many projects and failed them all. Grasp all, lose all.","burmese":"အားလုံးကို ဆွဲကိုင်ရင် အားလုံးဆုံးရှုံးမယ်။"},{"concept":"Hatred is as blind as love.","explanation":"Hatred, like love, can cloud a person's judgment.","example":"He attacked his rival without thinking. Hatred is as blind as love.","burmese":"အမုန်းက ချစ်ခြင်းလောက် မျက်စိကန်းတယ်။"},{"concept":"Ignorance is bliss.","explanation":"Not knowing something can sometimes make you happier.","example":"I don't want to know the spoilers. Ignorance is bliss.","burmese":"မသိခြင်းက ပျော်ရွှင်ခြင်းပဲ။"},{"concept":"If you want a friend, be a friend.","explanation":"To have friends, you must first be a good friend.","example":"Be kind to others if you want them to be kind to you. If you want a friend, be a friend.","burmese":"သူငယ်ချင်းလိုချင်ရင် သူငယ်ချင်းဖြစ်ပါ။"},{"concept":"Keep something for a rainy day.","explanation":"Save resources for a time of need.","example":"Don't spend all your salary. Keep something for a rainy day.","burmese":"မိုးရွာတဲ့နေ့အတွက် တစ်ခုခုထားပါ။"},{"concept":"Kill the goose that lays the golden eggs.","explanation":"Destroy something that produces valuable results for you.","example":"He fired his best worker and the company suffered. He killed the goose that lays the golden eggs.","burmese":"ရွှေဥဥတဲ့ ဘဲကြက်ကို သတ်ပစ်တယ်။"},{"concept":"Living well is the best revenge.","explanation":"The best response to those who wrong you is to live happily.","example":"After the breakup, she focused on her career. Living well is the best revenge.","burmese":"ကောင်းကောင်းနေထိုင်ခြင်းက အကောင်းဆုံးလက်စားချေခြင်းပဲ။"},{"concept":"Look after number one.","explanation":"Take care of yourself first.","example":"You can't help others if you're exhausted. Look after number one.","burmese":"ပထမဦးစားပေး ကိုယ့်ကိုယ်ကို ဂရုစိုက်ပါ။"},{"concept":"Lend only that which you can afford to lose.","explanation":"Only lend what you can afford not to get back.","example":"I only lend small amounts. Lend only that which you can afford to lose.","burmese":"ဆုံးရှုံးနိုင်တဲ့ပမာဏပဲ ချေးပါ။"},{"concept":"Make hay while the sun shines.","explanation":"Take advantage of favorable conditions while they last.","example":"Business is booming now, so expand. Make hay while the sun shines.","burmese":"နေရောင်ရှိတုန်း မြက်ခြောက်လှပ်ပါ။"},{"concept":"Might is right.","explanation":"The powerful determine what is considered right.","example":"The stronger country won the dispute. Might is right.","burmese":"အားကြီးတာက မှန်တယ်။"},{"concept":"Mind your own business.","explanation":"Do not interfere in other people's affairs.","example":"Stop asking about my salary. Mind your own business.","burmese":"ကိုယ့်အလုပ်ကိုယ်လုပ်ပါ။"},{"concept":"More haste, less speed.","explanation":"Going too fast leads to mistakes and slows you down.","example":"Take your time with the assignment. More haste, less speed.","burmese":"အလျင်စောလေ အနှေးပိုလေ။"},{"concept":"One rotten apple spoils the whole bunch.","explanation":"One bad person can negatively influence an entire group.","example":"One lazy student affected the whole class. One rotten apple spoils the whole bunch.","burmese":"ပုပ်သောအသီးတစ်လုံးက အုပ်စုတစ်ခုလုံးကို ပျက်စေတယ်။"},{"concept":"Opportunity seldom knocks twice.","explanation":"Good opportunities are rare and should be seized.","example":"Apply for the scholarship now. Opportunity seldom knocks twice.","burmese":"အခွင့်အရေးက ရှားရှားပါးပါးလာတတ်တယ်။"},{"concept":"Out of sight, out of mind.","explanation":"When something is not seen, it is easily forgotten.","example":"I haven't thought about my old school in years. Out of sight, out of mind.","burmese":"မျက်မှောက်မှာ မရှိရင် စိတ်ထဲက ပျောက်သွားတယ်။"},{"concept":"Prevention is better than cure.","explanation":"It is better to stop something bad from happening than to fix it later.","example":"Get vaccinated now. Prevention is better than cure.","burmese":"ကာကွယ်ခြင်းက ကုသခြင်းထက် ပိုကောင်းတယ်။"},{"concept":"Rome was not built in a day.","explanation":"Important achievements take time and patience.","example":"Learning a language takes years. Rome was not built in a day.","burmese":"ရောမမြို့ကို တစ်နေ့ထဲနဲ့ မဆောက်နိုင်ဘူး။"},{"concept":"Solitude is often the best company.","explanation":"Being alone can be more enjoyable than being with others.","example":"She enjoys reading alone. Solitude is often the best company.","burmese":"တစ်ယောက်တည်းနေခြင်းက အကောင်းဆုံးအဖော်ဖြစ်တတ်တယ်။"},{"concept":"The longest night will have an end.","explanation":"Even the most difficult times will eventually pass.","example":"Don't give up during hard times. The longest night will have an end.","burmese":"အရှည်ဆုံးညက အဆုံးရှိတယ်။"},{"concept":"The pen is mightier than the sword.","explanation":"Words and ideas have more influence than violence.","example":"The protest was peaceful but changed the law. The pen is mightier than the sword.","burmese":"ဘောပင်က ဓားထက် ပိုအားကြီးတယ်။"},{"concept":"The last straw breaks the camel's back.","explanation":"A small final burden causes something to fail.","example":"After years of stress, one more problem made her quit. The last straw breaks the camel's back.","burmese":"ကုန်းကူးကြက်ရဲ့ နောက်ဆုံးဖိတဲ့ နွားခြောက်ပွင့်ပဲ။"},{"concept":"The early bird catches the worm.","explanation":"Success comes to those who act early and prepare well.","example":"She got the job because she applied first. The early bird catches the worm.","burmese":"အစောပိုင်းငှက်က ပုရွက်ဆိတ်ကို ဖမ်းမိတယ်။"},{"concept":"Time cures all ills.","explanation":"Given enough time, problems and suffering will fade.","example":"You'll feel better after a few months. Time cures all ills.","burmese":"အချိန်က အနာတရအားလုံးကို ကုသပေးတယ်။"},{"concept":"There is a time to speak and a time to be silent.","explanation":"It is important to know when to talk and when to stay quiet.","example":"During the negotiation, she chose her words carefully. There is a time to speak and a time to be silent.","burmese":"ပြောရမယ့်အချိန်ရှိတယ်၊ ငြိမ်နေရမယ့်အချိန်ရှိတယ်။"},{"concept":"There is truth in wine.","explanation":"People reveal their true feelings when they are drunk.","example":"He confessed his love after drinking. There is truth in wine.","burmese":"စပျစ်ရည်ထဲမှာ မှန်ကန်မှုရှိတယ်။"},{"concept":"When in Rome do as Romans do.","explanation":"When in a new place, follow the customs of the people there.","example":"In Japan, you remove your shoes indoors. When in Rome do as Romans do.","burmese":"ရောမမှာနေရင် ရောမလူတွေလို လုပ်ပါ။"},{"concept":"What will be, will be.","explanation":"The future is determined and cannot be changed.","example":"Don't worry too much about tomorrow. What will be, will be.","burmese":"ဖြစ်မည့်အရာက ဖြစ်မှာပဲ။"},{"concept":"What's done is done.","explanation":"The past cannot be changed, so move on.","example":"Stop regretting the past. What's done is done.","burmese":"ပြီးသွားတာက ပြီးသွားပြီ။"},{"concept":"Words have wings and cannot be recalled.","explanation":"Once spoken, words cannot be taken back.","example":"Think before you speak. Words have wings and cannot be recalled.","burmese":"စကားက အတောင်ရှိပြီး ပြန်မခေါ်နိုင်ဘူး။"},{"concept":"Words cut more than swords.","explanation":"Hurtful words cause deeper wounds than physical weapons.","example":"His insults hurt her deeply. Words cut more than swords.","burmese":"စကားက ဓားထက် ပိုဖြတ်တယ်။"},{"concept":"You can't take it with you when you die.","explanation":"Material wealth cannot be taken to the afterlife.","example":"Enjoy life now, not just working. You can't take it with you when you die.","burmese":"သေတဲ့အခါ ဘာမှ မခေါ်သွားနိုင်ဘူး။"},{"concept":"You can't please everyone.","explanation":"It is impossible to satisfy every person.","example":"Some people liked the movie, others didn't. You can't please everyone.","burmese":"အားလုံးကို ကျေနပ်အောင် လုပ်လို့မရဘူး။"},{"concept":"You can't make an omelette without breaking egg.","explanation":"Achieving something worthwhile requires sacrifice.","example":"Starting a business is risky. You can't make an omelette without breaking egg.","burmese":"ဥကြက်ကြော်လုပ်ဖို့ ဥကွဲအောင် လုပ်ရတယ်။"}]}$$::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00047000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 47), 'unit47-ex1', 'multiple_choice', 'Choose the correct meaning of the proverb.', $$[{"id":4701,"question":"What does 'A leopard cannot change its spots' mean?","options":["People cannot change their fundamental nature","Leopards have unique patterns","Animals can adapt to new environments"],"answer":"People cannot change their fundamental nature","explanation":"'A leopard cannot change its spots' means people cannot change their fundamental nature. 'A leopard cannot change its spots' ဆိုတာ လူတစ်ယောက်ရဲ့ မူလသဘာဝကို ပြောင်းလဲလို့မရဘူး။","points":1},{"id":4702,"question":"What does 'A fool and his money are soon parted' mean?","options":["Rich people are generous","A foolish person quickly loses their money","Money is hard to earn"],"answer":"A foolish person quickly loses their money","explanation":"'A fool and his money are soon parted' means a foolish person quickly loses their money. 'A fool and his money are soon parted' ဆိုတာ အသိဥာဏ်နည်းတဲ့လူက ငွေကိုမြန်မြန်ဆုံးရှုံးတတ်တယ်။","points":1},{"id":4703,"question":"What does 'A barking dog seldom bites' mean?","options":["Dogs are dangerous","People who make loud threats rarely carry them out","Barking is a sign of aggression"],"answer":"People who make loud threats rarely carry them out","explanation":"'A barking dog seldom bites' means people who make loud threats rarely carry them out. 'A barking dog seldom bites' ဆိုတာ အော်ဟစ်ခြိမ်းခြောက်တတ်တဲ့လူက ရှားရှားပါးပါး လုပ်တတ်တယ်။","points":1},{"id":4704,"question":"What does 'A mouse may help a lion' mean?","options":["Mice are brave animals","Even small or weak beings can help the powerful","Lions need help from others"],"answer":"Even small or weak beings can help the powerful","explanation":"'A mouse may help a lion' means even small or weak beings can help the powerful. 'A mouse may help a lion' ဆိုတာ အားနည်းတဲ့လူက အားကြီးတဲ့လူကို ကူညီနိုင်တယ်။","points":1},{"id":4705,"question":"What does 'All that glitters is not gold' mean?","options":["Gold is valuable","Something that looks valuable or attractive may not be so","Glittering things are always expensive"],"answer":"Something that looks valuable or attractive may not be so","explanation":"'All that glitters is not gold' means something that looks valuable or attractive may not be so. 'All that glitters is not gold' ဆိုတာ တောက်ပတဲ့အရာအားလုံး ရွှေမဟုတ်ဘူး။","points":1},{"id":4706,"question":"What does 'Blood is thicker than water' mean?","options":["Blood is denser than water","Family relationships are stronger than other relationships","Blood has special properties"],"answer":"Family relationships are stronger than other relationships","explanation":"'Blood is thicker than water' means family relationships are stronger than other relationships. 'Blood is thicker than water' ဆိုတာ သွေးသားဆက်ဆံက ရေထက်ပိုထူတယ်။","points":1},{"id":4707,"question":"What does 'Better late than never' mean?","options":["Being late is always acceptable","It is better to do something late than not at all","Never being late is important"],"answer":"It is better to do something late than not at all","explanation":"'Better late than never' means it is better to do something late than not at all. 'Better late than never' ဆိုတာ နောက်ကျပေမယ့် မလုပ်တာထက်ပိုကောင်းတယ်။","points":1},{"id":4708,"question":"What does 'Charity begins at home' mean?","options":["Charity organizations should be based at home","One should take care of family first before helping others","Home is the best place to give charity"],"answer":"One should take care of family first before helping others","explanation":"'Charity begins at home' means one should take care of family first before helping others. 'Charity begins at home' ဆိုတာ ကျေးဇူးပြုခြင်းက အိမ်မှာစတင်တယ်။","points":1},{"id":4709,"question":"What does 'Don't put all your eggs in one basket' mean?","options":["Eggs are fragile","Do not risk everything on a single plan or opportunity","Carry eggs carefully"],"answer":"Do not risk everything on a single plan or opportunity","explanation":"'Don't put all your eggs in one basket' means do not risk everything on a single plan or opportunity. 'Don't put all your eggs in one basket' ဆိုတာ ဥအုန်းအားလုံးကို ခြင်းတစ်ခုထဲမှာ မထားပါနဲ့။","points":1},{"id":4710,"question":"What does 'Every cloud has a silver lining' mean?","options":["Clouds are silver in color","There is something good in every bad situation","Silver is valuable"],"answer":"There is something good in every bad situation","explanation":"'Every cloud has a silver lining' means there is something good in every bad situation. 'Every cloud has a silver lining' ဆိုတာ မိုးတိမ်တိုင်းရဲ့ ငွေရောင်အစွန်းရှိတယ်။","points":1},{"id":4711,"question":"What does 'Easy come, easy go' mean?","options":["Easy tasks are fun","What is gained easily is lost easily","Life should be easy"],"answer":"What is gained easily is lost easily","explanation":"'Easy come, easy go' means what is gained easily is lost easily. 'Easy come, easy go' ဆိုတာ လွယ်လွယ်ရတာ လွယ်လွယ်ဆုံးရှုံးတယ်။","points":1},{"id":4712,"question":"What does 'Familiarity breeds contempt' mean?","options":["Familiarity is good","Too much closeness leads to a lack of respect","Being familiar with something is bad"],"answer":"Too much closeness leads to a lack of respect","explanation":"'Familiarity breeds contempt' means too much closeness leads to a lack of respect. 'Familiarity breeds contempt' ဆိုတာ ရင်းနှီးမှုက အထင်အမြင်သေးခြင်းကို ဖန်တီးတယ်။","points":1},{"id":4713,"question":"What does 'Grasp all, lose all' mean?","options":["Holding things tightly is good","If you try to hold on to everything, you will lose everything","Having many things is beneficial"],"answer":"If you try to hold on to everything, you will lose everything","explanation":"'Grasp all, lose all' means if you try to hold on to everything, you will lose everything. 'Grasp all, lose all' ဆိုတာ အားလုံးကို ဆွဲကိုင်ရင် အားလုံးဆုံးရှုံးမယ်။","points":1},{"id":4714,"question":"What does 'Gardens are not made by sitting in the shade' mean?","options":["Gardens need sunlight","Success requires effort and hard work","Resting is important"],"answer":"Success requires effort and hard work","explanation":"'Gardens are not made by sitting in the shade' means success requires effort and hard work. 'Gardens are not made by sitting in the shade' ဆိုတာ ဥယျာဉ်ကို အရိပ်ထဲမှာ ထိုင်ပြီး ဖန်တီးလို့မရဘူး။","points":1},{"id":4715,"question":"What does 'The pen is mightier than the sword' mean?","options":["Writing tools are stronger than weapons","Words and ideas have more influence than violence","Pens are made of strong material"],"answer":"Words and ideas have more influence than violence","explanation":"'The pen is mightier than the sword' means words and ideas have more influence than violence. 'The pen is mightier than the sword' ဆိုတာ ဘောပင်က ဓားထက် ပိုအားကြီးတယ်။","points":1},{"id":4716,"question":"What does 'The early bird catches the worm' mean?","options":["Birds eat worms","Success comes to those who act early and prepare well","Worms are caught in the morning"],"answer":"Success comes to those who act early and prepare well","explanation":"'The early bird catches the worm' means success comes to those who act early and prepare well. 'The early bird catches the worm' ဆိုတာ အစောပိုင်းငှက်က ပုရွက်ဆိတ်ကို ဖမ်းမိတယ်။","points":1},{"id":4717,"question":"What does 'Prevention is better than cure' mean?","options":["Preventing disease is important","It is better to stop something bad from happening than to fix it later","Curing diseases is impossible"],"answer":"It is better to stop something bad from happening than to fix it later","explanation":"'Prevention is better than cure' means it is better to stop something bad from happening than to fix it later. 'Prevention is better than cure' ဆိုတာ ကာကွယ်ခြင်းက ကုသခြင်းထက် ပိုကောင်းတယ်။","points":1},{"id":4718,"question":"What does 'Rome was not built in a day' mean?","options":["Rome is an old city","Important achievements take time and patience","Building cities is difficult"],"answer":"Important achievements take time and patience","explanation":"'Rome was not built in a day' means important achievements take time and patience. 'Rome was not built in a day' ဆိုတာ ရောမမြို့ကို တစ်နေ့ထဲနဲ့ မဆောက်နိုင်ဘူး။","points":1},{"id":4719,"question":"What does 'When in Rome do as Romans do' mean?","options":["Visit Rome for tourism","When in a new place, follow the customs of the people there","Roman culture is superior"],"answer":"When in a new place, follow the customs of the people there","explanation":"'When in Rome do as Romans do' means when in a new place, follow the customs of the people there. 'When in Rome do as Romans do' ဆိုတာ ရောမမှာနေရင် ရောမလူတွေလို လုပ်ပါ။","points":1},{"id":4720,"question":"What does 'Words cut more than swords' mean?","options":["Swords are not dangerous","Hurtful words cause deeper wounds than physical weapons","Words are sharper than swords"],"answer":"Hurtful words cause deeper wounds than physical weapons","explanation":"'Words cut more than swords' means hurtful words cause deeper wounds than physical weapons. 'Words cut more than swords' ဆိုတာ စကားက ဓားထက် ပိုဖြတ်တယ်။","points":1}]$$::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00047001-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 47), 'unit47-ex2', 'multiple_choice', 'Choose the proverb that best fits the given situation.', $$[{"id":4721,"question":"Your friend is worried about the future. Which proverb should you tell them?","options":["The early bird catches the worm","What will be, will be","Easy come, easy go"],"answer":"What will be, will be","explanation":"'What will be, will be' is used to reassure someone that the future is determined and cannot be changed. 'What will be, will be' ဆိုတာ ဖြစ်မည့်အရာက ဖြစ်မှာပဲ။","points":1},{"id":4722,"question":"Someone spent all their money on a risky investment. Which proverb describes this?","options":["All covet, all lose","Don't look a gift horse in the mouth","More haste, less speed"],"answer":"All covet, all lose","explanation":"'All covet, all lose' means greed causes people to lose everything. Spending all money on a risky investment fits this proverb. 'All covet, all lose' ဆိုတာ တစ်ခုတည်းကို လိုချင်ရင် ဆုံးရှုံးတတ်တယ်။","points":1},{"id":4723,"question":"You got a free gift but it has a small defect. Which proverb applies?","options":["Don't judge a book by its cover","Don't look a gift horse in the mouth","Easy come, easy go"],"answer":"Don't look a gift horse in the mouth","explanation":"'Don't look a gift horse in the mouth' means do not criticize something given to you for free. 'Don't look a gift horse in the mouth' ဆိုတာ လက်ဆောင်ရတဲ့မြင်းရဲ့ပါးစပ်ကို မကြည့်ပါနဲ့။","points":1},{"id":4724,"question":"A team fails because one lazy member doesn't do their work. Which proverb fits?","options":["One rotten apple spoils the whole bunch","A friend to all is a friend to none","Might is right"],"answer":"One rotten apple spoils the whole bunch","explanation":"'One rotten apple spoils the whole bunch' means one bad person can negatively influence an entire group. 'One rotten apple spoils the whole bunch' ဆိုတာ ပုပ်သောအသီးတစ်လုံးက အုပ်စုတစ်ခုလုံးကို ပျက်စေတယ်။","points":1},{"id":4725,"question":"You should save some money for unexpected expenses. Which proverb tells you this?","options":["Make hay while the sun shines","Keep something for a rainy day","Lend only that which you can afford to lose"],"answer":"Keep something for a rainy day","explanation":"'Keep something for a rainy day' means save resources for a time of need. 'Keep something for a rainy day' ဆိုတာ မိုးရွာတဲ့နေ့အတွက် တစ်ခုခုထားပါ။","points":1},{"id":4726,"question":"A person who talks a lot but knows very little. Which proverb describes them?","options":["Empty vessels make the greatest song","Fools are wise as long as silent","A barking dog seldom bites"],"answer":"Empty vessels make the greatest song","explanation":"'Empty vessels make the greatest song' means people with little knowledge often talk the most. 'Empty vessels make the greatest song' ဆိုတာ အလွတ်ဗူးက အကြီးဆုံးအသံထွက်တယ်။","points":1},{"id":4727,"question":"You want to visit a new country and follow their customs. Which proverb applies?","options":["When in Rome do as Romans do","Blood is thicker than water","Out of sight, out of mind"],"answer":"When in Rome do as Romans do","explanation":"'When in Rome do as Romans do' means when in a new place, follow the customs of the people there. 'When in Rome do as Romans do' ဆိုတာ ရောမမှာနေရင် ရောမလူတွေလို လုပ်ပါ။","points":1},{"id":4728,"question":"Someone is trying to change their fundamental personality. Which proverb warns them?","options":["A leopard cannot change its spots","What's done is done","Time cures all ills"],"answer":"A leopard cannot change its spots","explanation":"'A leopard cannot change its spots' means people cannot change their fundamental nature. 'A leopard cannot change its spots' ဆိုတာ လူတစ်ယောက်ရဲ့ မူလသဘာဝကို ပြောင်းလဲလို့မရဘူး။","points":1},{"id":4729,"question":"A friend betrayed your trust after being close for a long time. Which proverb fits?","options":["Familiarity breeds contempt","A friend to all is a friend to none","Grasp all, lose all"],"answer":"Familiarity breeds contempt","explanation":"'Familiarity breeds contempt' means too much closeness leads to a lack of respect. 'Familiarity breeds contempt' ဆိုတာ ရင်းနှီးမှုက အထင်အမြင်သေးခြင်းကို ဖန်တီးတယ်။","points":1},{"id":4730,"question":"You should start working now while conditions are favorable. Which proverb tells you this?","options":["Make hay while the sun shines","The longest night will have an end","Time cures all ills"],"answer":"Make hay while the sun shines","explanation":"'Make hay while the sun shines' means take advantage of favorable conditions while they last. 'Make hay while the sun shines' ဆိုတာ နေရောင်ရှိတုန်း မြက်ခြောက်လှပ်ပါ။","points":1}]$$::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 48: Translation (From Myanmar to English)
-- --------------------------------------------------------------------------

INSERT INTO units (id, unit_number, title, lesson_count, exercise_count, question_count)
VALUES ('00000048-0000-4000-8000-000000000001', 48, 'Translation (From Myanmar to English)', 1, 2, 22)
ON CONFLICT (unit_number) DO UPDATE SET
  id = EXCLUDED.id,
  title = EXCLUDED.title,
  lesson_count = EXCLUDED.lesson_count,
  exercise_count = EXCLUDED.exercise_count,
  question_count = EXCLUDED.question_count;

INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00048000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 48), 'unit48-lesson1', 'Myanmar to English Translation: Practice and Understanding', 'Translation from Myanmar to English requires understanding both languages'' sentence structures. This lesson covers common translation patterns with examples from the source text.', $${"details":[{"concept":"Example 1: Hobbies and Habits","explanation":"Translating sentences about personal habits and their effects.","example":"လူတိုင်းတိုင်း / ဝါသနာကိုယ်စီ / ရှိကြသည်။ → Everybody / has / his or her own hobby.","burmese":"ဝါသနာ = hobby, ကိုယ်စီ = each one's own"},{"concept":"Example 2: Youth and Future","explanation":"Translating sentences about youth leadership and national future.","example":"လူငယ်များကို / အနာဂတ်၏ခေါင်းဆောင်များ → We proudly say that / youths / are / leaders of future.","burmese":"အနာဂတ် = future, ခေါင်းဆောင် = leader"},{"concept":"Example 3: Climate and Forests","explanation":"Translating sentences about environmental issues.","example":"ကမ္ဘာ့ရာသီဥတု ပြောင်းလဲမှုနှင့် / ကမ္ဘာ့က ပို့ လောင်စာတို့က → The world climate change and / global warming / are completely depending on / forests of the world.","burmese":"ရာသီဥတု = climate, လောင်စာ = fuel, သစ်တော = forest"},{"concept":"Example 4: International Forest Day","explanation":"Translating sentences about international designations.","example":"ယနေ့သည် / အပြည်ပြည်ဆိုင်ရာ သစ်တောနေ့ ဖြစ်ပါသည်။ → Today / is / the International Forests Day.","burmese":"အပြည်ပြည်ဆိုင်ရာ = international, သစ်တောနေ့ = Forest Day"},{"concept":"Example 5: Environmental Protection","explanation":"Translating sentences about environmental conservation.","example":"ယနေ့ကျွန်မတို့ / သဘာဝပတ်ဝန်းကျင် ပျက်ယွင်းမှုမရှိ စေရအတွက် → Today, / it is found that / people / come to seriously talk about / the national environment / not to be depleted.","burmese":"သဘာဝပတ်ဝန်းကျင် = natural environment, ပျက်ယွင်း = depleted"},{"concept":"Example 6: Climate Change Processes","explanation":"Translating complex sentences about climate change effects.","example":"ရာသီဥတု ပြောင်းလဲဖြစ်ပေါ်ခြင်းသည် → In parallel with time / through the media, / it is found that / the process of climate change / in various forms / is occurring / all over the world.","burmese":"ပြောင်းလဲဖြစ်ပေါ်ခြင်း = change process, ဖြစ်ပေါ်နေသည် = occurring"},{"concept":"Example 7: Natural Disasters","explanation":"Translating sentences about natural disasters and prevention.","example":"ရာသီဥတု ပြောင်းလဲမှုအတွင်း / ကမ္ဘာတစ်ဝန်းမှာမနေနိုင်သည့် သဘာဝဘေးအန္တရာယ် → We have noticed that / with the changing climates, / more and more unexpected natural disasters / occur / year after year.","burmese":"သဘာဝဘေးအန္တရာယ် = natural disaster, ကပ်ရောဂါ = epidemic"},{"concept":"Example 8: Renewable Energy","explanation":"Translating sentences about energy and environmental policy.","example":"ကမ္ဘာ့က ပို့ လောင်စာတို့ကို လျှော့ချရန်သည် → Most of the world nations / are striving / to extensively exploit / the renewable energies.","burmese":"လောင်စာ = fuel, စွမ်းအင် = energy, ကြိုးပမ်း = strive"},{"concept":"Example 9: Science and Technology","explanation":"Translating sentences about technological development.","example":"မကြာမကြာ ကျက်လတ်တိုင်း / သိပ္ပံနည်းပညာများသည် → At present, / Sciences and Technologies / are improving / with momentum.","burmese":"သိပ္ပံနည်းပညာ = science and technology, တိုးတက် = improve"},{"concept":"Example 10: Youth Leadership","explanation":"Translating sentences about youth in the information age.","example":"အင်ဖော်မေရှင်နည်းပညာများ တိုးတက်လာသည်ဖြင့် → With the improvement of the Information Technologies, / the leadership role / of new generations / gradually / becomes wide.","burmese":"အင်ဖော်မေရှင် = information, ဦးဆောင်မှု = leadership"},{"concept":"Example 11: Communication Technologies","explanation":"Translating sentences about global communication and culture.","example":"ယနေ့ကမ္ဘာတစ်ဝန်းတွင် / ဆက်သွယ်ရေးနည်းပညာများသည် → In the world today, / Communication Technologies / are wonderfully developing.","burmese":"ဆက်သွယ်ရေး = communication, ဓလေ့စတိုင် = culture"},{"concept":"Example 12: Altruism","explanation":"Translating sentences about altruism and service.","example":"ပရဟိတစိတ်ဓာတ်ဟာသည် / အများအကျိုးသယ်ပိုးကြွေးမြွက်သည့် → Altruism / is the spirit / to serve the interest of others.","burmese":"ပရဟိတ = altruism, စိတ်ဓာတ် = spirit, သယ်ပိုးကြွေးမြွက် = serve"},{"concept":"Example 13: Myanmar Women","explanation":"Translating sentences about cultural traditions and women.","example":"မြန်မာလူ့ ဘာသာအဖွဲ့အစည်းတွင် / မြန်မာအမျိုးသမီးများသည် → In Myanmar Society, / Myanmar women / are polite and gentle / in accordance with traditional customs.","burmese":"ဓလေ့ထုံးတမ်း = traditional customs, ယဉ်ကျေး = polite"},{"concept":"Example 14: Education Promotion","explanation":"Translating sentences about education and development.","example":"ပညာရေးမြှင့်တင်မှုအစအစများအရ → According to the Education Promotion Programme, / modern educated developments / such as international standard education.","burmese":"ပညာရေး = education, မြှင့်တင် = promote, အတတ်ပညာ = skill"}]}$$::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00048000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 48), 'unit48-ex1', 'multiple_choice', 'Choose the correct English translation of the Myanmar phrase.', $$[{"id":4801,"question":"What does 'ဝါသနာကိုယ်စီ' mean in English?","options":["each person's hobby","everyone's job","personal opinion"],"answer":"each person's hobby","explanation":"'ဝါသနာကိုယ်စီ' means 'each person's hobby' or 'his or her own hobby'. 'ဝါသနာ' = hobby, 'ကိုယ်စီ' = each one's own.","points":1},{"id":4802,"question":"What does 'အနာဂတ်၏ခေါင်းဆောင်များ' mean in English?","options":["leaders of the past","leaders of the future","current leaders"],"answer":"leaders of the future","explanation":"'အနာဂတ်၏ခေါင်းဆောင်များ' means 'leaders of the future'. 'အနာဂတ်' = future, 'ခေါင်းဆောင်' = leader.","points":1},{"id":4803,"question":"What does 'သစ်တောများ' mean in English?","options":["mountains","forests","rivers"],"answer":"forests","explanation":"'သစ်တောများ' means 'forests'. 'သစ်တော' = forest, 'များ' = plural marker.","points":1},{"id":4804,"question":"What does 'အပြည်ပြည်ဆိုင်ရာ သစ်တောနေ့' mean in English?","options":["National Forest Day","International Forests Day","World Tree Day"],"answer":"International Forests Day","explanation":"'အပြည်ပြည်ဆိုင်ရာ သစ်တောနေ့' means 'International Forests Day'. 'အပြည်ပြည်ဆိုင်ရာ' = international, 'သစ်တောနေ့' = Forest Day.","points":1},{"id":4805,"question":"What does 'သဘာဝပတ်ဝန်းကျင်' mean in English?","options":["artificial environment","natural environment","urban environment"],"answer":"natural environment","explanation":"'သဘာဝပတ်ဝန်းကျင်' means 'natural environment'. 'သဘာဝ' = natural, 'ပတ်ဝန်းကျင်' = environment.","points":1},{"id":4806,"question":"What does 'ပြောင်းလဲမှု' mean in English?","options":["improvement","change","destruction"],"answer":"change","explanation":"'ပြောင်းလဲမှု' means 'change' or 'transformation'. It refers to the process of changing.","points":1},{"id":4807,"question":"What does 'သဘာဝဘေးအန္တရာယ်' mean in English?","options":["man-made disaster","natural disaster","economic crisis"],"answer":"natural disaster","explanation":"'သဘာဝဘေးအန္တရာယ်' means 'natural disaster'. 'သဘာဝ' = natural, 'ဘေးအန္တရာယ်' = disaster.","points":1},{"id":4808,"question":"What does 'စွမ်းအင်' mean in English?","options":["resource","energy","power"],"answer":"energy","explanation":"'စွမ်းအင်' means 'energy'. It is used in contexts like renewable energy (ပြန်လည်သုံးစွဲနိုင်သည့် စွမ်းအင်).","points":1},{"id":4809,"question":"What does 'သိပ္ပံနည်းပညာ' mean in English?","options":["art and culture","science and technology","mathematics and science"],"answer":"science and technology","explanation":"'သိပ္ပံနည်းပညာ' means 'science and technology'. 'သိပ္ပံ' = science, 'နည်းပညာ' = technology.","points":1},{"id":4810,"question":"What does 'ဆက်သွယ်ရေးနည်းပညာ' mean in English?","options":["transportation technology","communication technology","medical technology"],"answer":"communication technology","explanation":"'ဆက်သွယ်ရေးနည်းပညာ' means 'communication technology'. 'ဆက်သွယ်ရေး' = communication, 'နည်းပညာ' = technology.","points":1},{"id":4811,"question":"What does 'ပရဟိတစိတ်ဓာတ်' mean in English?","options":["selfish spirit","altruism","competitive spirit"],"answer":"altruism","explanation":"'ပရဟိတစိတ်ဓာတ်' means 'altruism' - the spirit to serve the interest of others. 'ပရဟိတ' = altruism, 'စိတ်ဓာတ်' = spirit.","points":1},{"id":4812,"question":"What does 'ဓလေ့ထုံးတမ်း' mean in English?","options":["modern trends","traditional customs","new regulations"],"answer":"traditional customs","explanation":"'ဓလေ့ထုံးတမ်း' means 'traditional customs'. 'ဓလေ့' = custom, 'ထုံးတမ်း' = tradition.","points":1}]$$::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;
INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00048001-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 48), 'unit48-ex2', 'multiple_choice', 'Choose the correct Myanmar phrase that matches the English translation.', $$[{"id":4813,"question":"Which Myanmar phrase means 'each person's own hobby'?","options":["ဝါသနာကိုယ်စီ","ဘာသာစကားကိုယ်စီ","အလုပ်ကိုယ်စီ"],"answer":"ဝါသနာကိုယ်စီ","explanation":"'ဝါသနာကိုယ်စီ' means 'each person's own hobby'. 'ဝါသနာ' = hobby, 'ကိုယ်စီ' = each one's own.","points":1},{"id":4814,"question":"Which Myanmar phrase means 'leaders of the future'?","options":["အတိတ်၏ခေါင်းဆောင်များ","အနာဂတ်၏ခေါင်းဆောင်များ","လက်ရှိခေါင်းဆောင်များ"],"answer":"အနာဂတ်၏ခေါင်းဆောင်များ","explanation":"'အနာဂတ်၏ခေါင်းဆောင်များ' means 'leaders of the future'. 'အနာဂတ်' = future, 'ခေါင်းဆောင်' = leader.","points":1},{"id":4815,"question":"Which Myanmar phrase means 'natural environment'?","options":["သဘာဝပတ်ဝန်းကျင်","လူလုပ်ပတ်ဝန်းကျင်","မြို့ပြပတ်ဝန်းကျင်"],"answer":"သဘာဝပတ်ဝန်းကျင်","explanation":"'သဘာဝပတ်ဝန်းကျင်' means 'natural environment'. 'သဘာဝ' = natural, 'ပတ်ဝန်းကျင်' = environment.","points":1},{"id":4816,"question":"Which Myanmar phrase means 'International Forests Day'?","options":["အမျိုးသားသစ်တောနေ့","အပြည်ပြည်ဆိုင်ရာ သစ်တောနေ့","ကမ္ဘာ့သစ်ပင်နေ့"],"answer":"အပြည်ပြည်ဆိုင်ရာ သစ်တောနေ့","explanation":"'အပြည်ပြည်ဆိုင်ရာ သစ်တောနေ့' means 'International Forests Day'. 'အပြည်ပြည်ဆိုင်ရာ' = international, 'သစ်တောနေ့' = Forest Day.","points":1},{"id":4817,"question":"Which Myanmar phrase means 'renewable energy'?","options":["ပြန်လည်သုံးစွဲနိုင်သည့် စွမ်းအင်","ဓာတ်ငွေ့စွမ်းအင်","လျှပ်စစ်စွမ်းအင်"],"answer":"ပြန်လည်သုံးစွဲနိုင်သည့် စွမ်းအင်","explanation":"'ပြန်လည်သုံးစွဲနိုင်သည့် စွမ်းအင်' means 'renewable energy'. 'ပြန်လည်' = renewable, 'စွမ်းအင်' = energy.","points":1},{"id":4818,"question":"Which Myanmar phrase means 'natural disaster'?","options":["သဘာဝဘေးအန္တရာယ်","လူလုပ်ဘေးအန္တရာယ်","စီးပွားဘေးအန္တရာယ်"],"answer":"သဘာဝဘေးအန္တရာယ်","explanation":"'သဘာဝဘေးအန္တရာယ်' means 'natural disaster'. 'သဘာဝ' = natural, 'ဘေးအန္တရာယ်' = disaster.","points":1},{"id":4819,"question":"Which Myanmar phrase means 'communication technology'?","options":["ဆက်သွယ်ရေးနည်းပညာ","ထုတ်လုပ်ရေးနည်းပညာ","သိပ္ပံနည်းပညာ"],"answer":"ဆက်သွယ်ရေးနည်းပညာ","explanation":"'ဆက်သွယ်ရေးနည်းပညာ' means 'communication technology'. 'ဆက်သွယ်ရေး' = communication, 'နည်းပညာ' = technology.","points":1},{"id":4820,"question":"Which Myanmar phrase means 'traditional customs'?","options":["ဓလေ့ထုံးတမ်း","ခေတ်ပေါ်ဓလေ့","နိုင်ငံတကာဓလေ့"],"answer":"ဓလေ့ထုံးတမ်း","explanation":"'ဓလေ့ထုံးတမ်း' means 'traditional customs'. 'ဓလေ့' = custom, 'ထုံးတမ်း' = tradition.","points":1},{"id":4821,"question":"Which Myanmar phrase means 'altruism'?","options":["ကိုယ်ကျိုးစီးပွား","ပရဟိတစိတ်ဓာတ်","အတ္ထုပ္ပတ္တိစိတ်ဓာတ်"],"answer":"ပရဟိတစိတ်ဓာတ်","explanation":"'ပရဟိတစိတ်ဓာတ်' means 'altruism' - the spirit to serve the interest of others. 'ပရဟိတ' = altruism, 'စိတ်ဓာတ်' = spirit.","points":1},{"id":4822,"question":"Which Myanmar phrase means 'science and technology'?","options":["ဘာသာစကားနည်းပညာ","သိပ္ပံနည်းပညာ","စီးပွားနည်းပညာ"],"answer":"သိပ္ပံနည်းပညာ","explanation":"'သိပ္ပံနည်းပညာ' means 'science and technology'. 'သိပ္ပံ' = science, 'နည်းပညာ' = technology.","points":1}]$$::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

